insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('1-f7bb1b7df2','aux-cm',1,'¿Cuáles son los valores superiores del ordenamiento jurídico según la Constitución?','["La libertad, la justicia, la igualdad y el pluralismo político", "La libertad, la seguridad, la igualdad y la solidaridad", "La justicia, la paz, la igualdad y la democracia", "La libertad, la justicia, la dignidad y el pluralismo político"]'::jsonb,0,'Art. 1.1 CE','España propugna como valores superiores la libertad, la justicia, la igualdad y el pluralismo político.','abr. 2026 · 1.er ejercicio'),
('1-3a4785b2ae','aux-cm',1,'Según la Constitución, la soberanía nacional reside en:','["Las Cortes Generales", "El pueblo español", "El Rey", "La Nación y las Comunidades Autónomas"]'::jsonb,1,'Art. 1.2 CE','La soberanía nacional reside en el pueblo español, del que emanan los poderes del Estado.',null),
('1-06746f7c78','aux-cm',1,'La forma política del Estado español es:','["La Monarquía constitucional", "El Estado autonómico", "La Monarquía parlamentaria", "La República federal"]'::jsonb,2,'Art. 1.3 CE','La forma política del Estado español es la Monarquía parlamentaria.',null),
('1-304ffeb21f','aux-cm',1,'Respecto al castellano, todos los españoles tienen:','["Solo el derecho a usarlo", "Solo el deber de conocerlo", "El derecho a conocerlo y el deber de usarlo", "El deber de conocerlo y el derecho a usarlo"]'::jsonb,3,'Art. 3.1 CE','Todos los españoles tienen el deber de conocer el castellano y el derecho a usarlo.',null),
('1-6e73cbfabf','aux-cm',1,'¿Cómo es la bandera de España según la Constitución?','["Tres franjas horizontales roja, amarilla y roja, siendo la amarilla de doble anchura que cada roja", "Tres franjas horizontales roja, amarilla y roja, las tres de la misma anchura entre sí", "Tres franjas verticales roja, amarilla y roja, siendo la amarilla de doble anchura que cada roja", "Tres franjas horizontales amarilla, roja y amarilla, siendo la roja de doble anchura que cada amarilla"]'::jsonb,0,'Art. 4.1 CE','Tres franjas horizontales roja, amarilla y roja, siendo la amarilla de doble anchura que cada una de las rojas.',null),
('1-89409afd52','aux-cm',1,'¿Cuál es la capital del Estado según la Constitución?','["La ciudad de Madrid y su área metropolitana", "La villa de Madrid", "La que determine una ley orgánica", "La sede del Gobierno, sea cual sea"]'::jsonb,1,'Art. 5 CE','La capital del Estado es la villa de Madrid.',null),
('1-46342895fd','aux-cm',1,'Según el art. 6, los partidos políticos:','["Son órganos del Estado", "Necesitan autorización administrativa previa", "Expresan el pluralismo político", "Pueden tener estructura interna no democrática"]'::jsonb,2,'Art. 6 CE','Los partidos expresan el pluralismo político y su estructura interna y funcionamiento deben ser democráticos.',null),
('1-45021caa23','aux-cm',1,'¿Cuál de estos principios NO garantiza el art. 9.3 de la Constitución?','["La publicidad de las normas", "La jerarquía normativa", "La interdicción de la arbitrariedad de los poderes públicos", "La retroactividad de las disposiciones sancionadoras desfavorables"]'::jsonb,3,'Art. 9.3 CE','Se garantiza lo contrario: la irretroactividad de las disposiciones sancionadoras no favorables o restrictivas de derechos individuales.',null),
('1-b7c7c86c75','aux-cm',1,'Las normas sobre derechos fundamentales se interpretan de conformidad con:','["La Declaración Universal de Derechos Humanos y los tratados ratificados por España", "La jurisprudencia del Tribunal Supremo y los tratados ratificados por España, en ese orden de prelación", "La Declaración Universal de Derechos Humanos y las leyes orgánicas que los desarrollen", "La doctrina del Tribunal Constitucional y los Estatutos de Autonomía vigentes"]'::jsonb,0,'Art. 10.2 CE','Se interpretan conforme a la Declaración Universal de Derechos Humanos y los tratados y acuerdos internacionales ratificados por España.',null),
('1-38009ccc70','aux-cm',1,'Según la Constitución, ¿puede un español de origen ser privado de su nacionalidad?','["Sí, por sentencia firme", "No, en ningún caso", "Sí, si adquiere otra nacionalidad", "Sí, por decisión del Gobierno"]'::jsonb,1,'Art. 11.2 CE','Ningún español de origen podrá ser privado de su nacionalidad.',null),
('1-5ba8a769af','aux-cm',1,'¿A qué edad son mayores de edad los españoles según la Constitución?','["16 años", "21 años", "18 años", "La fija cada Comunidad Autónoma"]'::jsonb,2,'Art. 12 CE','Los españoles son mayores de edad a los dieciocho años.',null),
('1-85c65a6b53','aux-cm',1,'Los extranjeros pueden ejercer el derecho de sufragio activo y pasivo:','["En las elecciones municipales y autonómicas, atendiendo a criterios de reciprocidad", "En las elecciones municipales, sin necesidad de criterios de reciprocidad", "En las elecciones municipales y europeas, siempre que residan en España", "En las elecciones municipales, atendiendo a criterios de reciprocidad"]'::jsonb,3,'Art. 13.2 CE','Solo los españoles son titulares del art. 23, salvo el sufragio activo y pasivo en las elecciones municipales con reciprocidad. Este apartado se reformó en 1992.',null),
('1-97f81199f6','aux-cm',1,'Según el art. 15 de la Constitución, la pena de muerte:','["Queda abolida, salvo lo que dispongan las leyes penales militares para tiempos de guerra", "Queda abolida, salvo para los delitos de terrorismo que determine una ley orgánica", "Queda abolida en todo caso, sin ninguna excepción en el texto constitucional", "Queda abolida, salvo lo que dispongan las leyes penales militares en estado de sitio"]'::jsonb,0,'Art. 15 CE','Queda abolida la pena de muerte, salvo lo que puedan disponer las leyes penales militares para tiempos de guerra.',null),
('1-a04cddfa42','aux-cm',1,'¿Cuánto puede durar como máximo la detención preventiva antes de poner al detenido en libertad o a disposición judicial?','["24 horas", "72 horas", "48 horas", "5 días"]'::jsonb,1,'Art. 17.2 CE','La detención preventiva no puede durar más de lo estrictamente necesario y, como máximo, 72 horas.',null),
('1-139477f6cb','aux-cm',1,'¿Qué procedimiento regula la ley para la inmediata puesta a disposición judicial de toda persona detenida ilegalmente?','["El recurso de amparo", "El recurso de inconstitucionalidad", "El habeas corpus", "La cuestión prejudicial"]'::jsonb,2,'Art. 17.4 CE','La ley regula el procedimiento de habeas corpus.',null),
('1-2a121ead68','aux-cm',1,'¿En qué casos se puede entrar en un domicilio según la Constitución?','["Con consentimiento del titular, resolución judicial o autorización de la autoridad gubernativa", "Solo con resolución judicial o en caso de flagrante delito", "Con consentimiento del titular o resolución judicial, pero nunca sin ellos", "Con consentimiento del titular, resolución judicial o en caso de flagrante delito"]'::jsonb,3,'Art. 18.2 CE','Ninguna entrada o registro sin consentimiento del titular o resolución judicial, salvo flagrante delito.',null),
('1-b1f141addd','aux-cm',1,'El secuestro de publicaciones y otros medios de información solo puede acordarse:','["En virtud de resolución judicial", "Por orden del Ministerio del Interior", "Por acuerdo del Consejo de Ministros", "Por la autoridad gubernativa en casos urgentes"]'::jsonb,0,'Art. 20.5 CE','Solo podrá acordarse el secuestro en virtud de resolución judicial.',null),
('1-e25bb7476f','aux-cm',1,'Para reuniones en lugares de tránsito público y manifestaciones se exige:','["Autorización previa de la autoridad", "Comunicación previa a la autoridad", "Autorización judicial", "Nada: son totalmente libres"]'::jsonb,1,'Art. 21.2 CE','Se da comunicación previa a la autoridad, que solo puede prohibirlas por razones fundadas de alteración del orden público.',null),
('1-8142a16254','aux-cm',1,'¿Qué asociaciones prohíbe expresamente la Constitución?','["Las secretas y las que persigan fines políticos", "Las no inscritas en el registro y las de carácter paramilitar", "Las secretas y las de carácter paramilitar", "Las de carácter paramilitar y las formadas solo por extranjeros"]'::jsonb,2,'Art. 22.5 CE','Se prohíben las asociaciones secretas y las de carácter paramilitar.',null),
('1-6c60d32fb0','aux-cm',1,'El art. 23.2 reconoce el derecho a acceder a las funciones y cargos públicos:','["En condiciones de igualdad, según el orden de antigüedad que fijen las leyes", "En condiciones de igualdad, siempre que se posea la nacionalidad española de origen", "Conforme a los méritos que libremente aprecie cada Administración", "En condiciones de igualdad, con los requisitos que señalen las leyes"]'::jsonb,3,'Art. 23.2 CE','Los ciudadanos tienen derecho a acceder en condiciones de igualdad a las funciones y cargos públicos, con los requisitos que señalen las leyes.',null),
('1-9a0130ef82','aux-cm',1,'Según el art. 24.2, todos tienen derecho:','["Al Juez ordinario predeterminado por la ley", "A elegir el juez que les juzgue", "A ser juzgados por un jurado en todo caso", "A un tribunal especial según su profesión"]'::jsonb,0,'Art. 24.2 CE','Todos tienen derecho al Juez ordinario predeterminado por la ley, a la defensa y a la asistencia de letrado, entre otros.',null),
('1-c843ecbdbf','aux-cm',1,'La Administración civil puede imponer sanciones que impliquen privación de libertad:','["Sí, en casos graves", "No, en ningún caso", "Sí, con autorización judicial posterior", "Solo durante el estado de alarma"]'::jsonb,1,'Art. 25.3 CE','La Administración civil no podrá imponer sanciones que, directa o subsidiariamente, impliquen privación de libertad.',null),
('1-53a8cc3343','aux-cm',1,'Según la Constitución, la enseñanza básica es:','["Voluntaria y gratuita", "Obligatoria y de pago", "Obligatoria y gratuita", "Voluntaria y de pago"]'::jsonb,2,'Art. 27.4 CE','La enseñanza básica es obligatoria y gratuita.',null),
('1-7c7c8408c5','aux-cm',1,'El derecho a la huelga de los trabajadores se reconoce en:','["El art. 37.2", "El art. 35.1", "El art. 7", "El art. 28.2"]'::jsonb,3,'Art. 28.2 CE','El art. 28.2 reconoce el derecho a la huelga de los trabajadores para la defensa de sus intereses.',null),
('1-0eebed2b69','aux-cm',1,'Según el art. 30.1, defender a España es para los españoles:','["Un derecho y un deber", "Solo un deber", "Solo un derecho", "Una obligación exclusiva de las Fuerzas Armadas"]'::jsonb,0,'Art. 30.1 CE','Los españoles tienen el derecho y el deber de defender a España.',null),
('1-dfbe9098b2','aux-cm',1,'El art. 32.1 reconoce el derecho a contraer matrimonio:','["Al hombre y la mujer, a partir de la edad que fije cada Comunidad Autónoma", "Al hombre y la mujer, con plena igualdad jurídica", "Al hombre y la mujer, previa autorización del Registro Civil", "A los españoles mayores de edad, en forma civil o religiosa"]'::jsonb,1,'Art. 32.1 CE','El hombre y la mujer tienen derecho a contraer matrimonio con plena igualdad jurídica.',null),
('1-ebd986484a','aux-cm',1,'¿Qué artículo modificó la reforma constitucional de 2024?','["El art. 135, sobre estabilidad presupuestaria", "El art. 13.2, sobre el sufragio de los extranjeros en elecciones municipales", "El art. 49, sobre las personas con discapacidad", "El art. 69.3, sobre la elección de los senadores provinciales"]'::jsonb,2,'Art. 49 CE','La reforma de febrero de 2024 modificó el art. 49. Las anteriores fueron la de 1992 (art. 13.2) y la de 2011 (art. 135); la de mayo de 2026 modificó el art. 69.3.',null),
('1-a27790b37a','aux-cm',1,'Según el art. 53.1, el ejercicio de los derechos del Capítulo II solo puede regularse:','["Por decreto-ley", "Por reglamento del Gobierno", "Por ley de las Comunidades Autónomas exclusivamente", "Por ley, que deberá respetar su contenido esencial"]'::jsonb,3,'Art. 53.1 CE','Vinculan a todos los poderes públicos y solo por ley, que respete su contenido esencial, podrá regularse su ejercicio.',null),
('1-bd2cd45b4c','aux-cm',1,'¿Qué derechos pueden protegerse mediante recurso de amparo ante el Tribunal Constitucional?','["El art. 14, la Sección 1.ª del Capítulo II y la objeción de conciencia del art. 30", "Todos los derechos del Capítulo II del Título I, incluida su Sección 2.ª", "El art. 14 y los principios rectores del Capítulo III del Título I", "La Sección 1.ª del Capítulo II, pero no la igualdad del art. 14"]'::jsonb,0,'Art. 53.2 CE','Cabe amparo para el art. 14, la Sección 1.ª del Capítulo II y la objeción de conciencia del art. 30, en su caso tras acudir a los tribunales ordinarios.',null),
('1-ba4eba36e6','aux-cm',1,'El Defensor del Pueblo es:','["Alto comisionado del Gobierno, designado por el Consejo de Ministros", "Alto comisionado de las Cortes Generales, designado por estas", "Alto comisionado de las Cortes Generales, designado por el Rey", "Alto comisionado del Consejo General del Poder Judicial"]'::jsonb,1,'Art. 54 CE','Es alto comisionado de las Cortes Generales, designado por ellas para la defensa de los derechos del Título I.',null),
('1-f78ae2e887','aux-cm',1,'Según el art. 55.1, los derechos pueden suspenderse cuando se declare el estado de:','["Alarma", "Alarma, excepción o sitio", "Excepción o sitio", "Solo sitio"]'::jsonb,2,'Art. 55.1 CE','La suspensión general cabe en el estado de excepción o de sitio, no en el de alarma.',null),
('1-f526f68a68','aux-cm',1,'La suspensión individual de derechos para investigaciones sobre bandas armadas o terrorismo se regula mediante:','["Real decreto", "Ley ordinaria", "Orden ministerial", "Ley orgánica"]'::jsonb,3,'Art. 55.2 CE','Una ley orgánica puede determinar la suspensión individual de los derechos de los arts. 17.2 y 18.2 y 3 en esas investigaciones.',null),
('2-5efe69f56d','aux-cm',2,'¿Qué norma aprueba el Estatuto de Autonomía de la Comunidad de Madrid?','["La Ley 1/1983 de la Asamblea de Madrid", "La Ley Orgánica 5/1998, de 7 de julio", "La Ley Orgánica 3/1983, de 25 de febrero", "El Real Decreto 1959/1983"]'::jsonb,2,'LO 3/1983','El Estatuto se aprobó por la LO 3/1983, de 25 de febrero. La LO 5/1998 lo reformó y la Ley 1/1983 es la de Gobierno y Administración.',null),
('2-75640ef450','aux-cm',2,'¿Qué Ley Orgánica reestructuró el Estatuto y dio nueva redacción a buena parte de sus artículos?','["La LO 2/1991", "La LO 10/1994", "La LO 3/2007", "La LO 5/1998"]'::jsonb,3,'LO 5/1998','La gran reforma fue la LO 5/1998. La LO 2/1991 solo modificó el art. 11.5 y la LO 10/1994 amplió competencias.',null),
('2-13061f8b45','aux-cm',2,'Según el Estatuto, el territorio de la Comunidad de Madrid:','["Comprende el de los municipios dentro de los límites de la provincia de Madrid", "Es el que fije en cada legislatura una ley aprobada por la Asamblea", "Coincide con el área metropolitana de la capital y sus municipios limítrofes", "Lo delimita el Gobierno de la Nación mediante real decreto"]'::jsonb,0,'Art. 2 EA','El territorio coincide con los límites de la provincia de Madrid.',null),
('2-e7f92beed6','aux-cm',2,'¿Cómo es la bandera de la Comunidad de Madrid?','["Roja con cinco estrellas blancas", "Roja carmesí con siete estrellas blancas", "Blanca con siete estrellas rojas", "Carmesí con siete estrellas doradas"]'::jsonb,1,'Art. 4.1 EA','La bandera es roja carmesí, con siete estrellas en blanco de cinco puntas.','nov. 2024 · 1.er ejercicio'),
('2-4e42e7207e','aux-cm',2,'¿Qué día es la fiesta de la Comunidad de Madrid según el Estatuto?','["El 15 de mayo", "El 12 de octubre", "El 2 de mayo", "El 9 de noviembre"]'::jsonb,2,'Art. 4.4 EA','Se declara fiesta de la Comunidad el 2 de mayo.',null),
('2-5e0af2601e','aux-cm',2,'El himno de la Comunidad de Madrid se establece:','["Por decreto del Gobierno", "Por acuerdo de la Mesa de la Asamblea", "En el propio texto del Estatuto", "Por ley de la Asamblea"]'::jsonb,3,'Art. 4.3 EA','La Comunidad tiene himno propio, establecido por ley de la Asamblea.',null),
('2-12ab17dbae','aux-cm',2,'¿Cuál es la capital de la Comunidad de Madrid y sede de sus instituciones?','["Madrid y Alcalá de Henares de forma compartida", "La villa de Madrid, aunque sus organismos pueden ubicarse en otros municipios", "La que fije la Asamblea en cada legislatura", "La villa de Madrid, donde deben estar obligatoriamente todos los organismos"]'::jsonb,1,'Art. 5 EA','La capital es la villa de Madrid, pero los organismos pueden establecerse en otros municipios de la Comunidad.',null),
('2-f5c1b8f738','aux-cm',2,'El régimen especial de la villa de Madrid como capital del Estado se regula por:','["Una ley de la Asamblea de Madrid", "Un decreto del Gobierno de la Comunidad", "Una ley votada en Cortes Generales", "El reglamento orgánico del Ayuntamiento"]'::jsonb,2,'Art. 6 EA','La villa de Madrid tiene un régimen especial regulado por ley votada en Cortes.',null),
('2-85ce3b6eca','aux-cm',2,'Las circunscripciones territoriales propias de la Comunidad se pueden crear:','["Por acuerdo de los plenos de los municipios limítrofes afectados", "Por decreto del Consejo de Gobierno, agrupando municipios limítrofes", "Por ley de las Cortes Generales, agrupando municipios limítrofes", "Por ley de la Asamblea, agrupando municipios limítrofes"]'::jsonb,3,'Art. 3.3 EA','La Asamblea puede establecer por ley circunscripciones territoriales propias agrupando municipios limítrofes.',null),
('2-b4939d14a0','aux-cm',2,'¿Cuáles son las instituciones de autogobierno de la Comunidad de Madrid?','["La Asamblea, el Gobierno y el Presidente", "La Asamblea, el Gobierno, el Presidente y el Tribunal Superior de Justicia", "La Asamblea y el Gobierno", "La Asamblea, el Gobierno y el Defensor del Pueblo"]'::jsonb,0,'Art. 8 EA','Los poderes se ejercen a través de la Asamblea, el Gobierno y el Presidente.',null),
('2-18ba190c45','aux-cm',2,'¿Gozan de los derechos políticos de los madrileños los españoles residentes en el extranjero?','["No, porque los derechos políticos exigen vecindad administrativa en Madrid", "Sí, si nacieron en la Comunidad de Madrid, aunque nunca residieran en ella", "Sí, si su última vecindad administrativa fue en Madrid y lo acreditan en el Consulado", "Sí, si residieron en Madrid al menos cinco años antes de marchar al extranjero"]'::jsonb,2,'Art. 7.3 EA','Gozan de ellos si su última vecindad administrativa fue Madrid y lo acreditan en el Consulado de España correspondiente.',null),
('2-390a9e2ce5','aux-cm',2,'¿Cada cuántos años se elige la Asamblea de Madrid?','["Cinco años", "Tres años", "Seis años", "Cuatro años"]'::jsonb,3,'Art. 10.1 EA','La Asamblea se elige por cuatro años.',null),
('2-c79a8bc70b','aux-cm',2,'¿Cuántos diputados componen la Asamblea de Madrid?','["Uno por cada 50.000 habitantes o fracción superior a 25.000", "Uno por cada 40.000 habitantes o fracción superior a 20.000", "Un número fijo de 129", "Uno por cada 100.000 habitantes"]'::jsonb,0,'Art. 10.2 EA','El número depende de la población: uno por cada 50.000 habitantes o fracción superior a 25.000.','oct. 2026 · 1.er ejercicio'),
('2-9d5f179c91','aux-cm',2,'¿Cuál es la circunscripción electoral para las elecciones a la Asamblea?','["Cada municipio", "La provincia", "Cada partido judicial", "Cada comarca"]'::jsonb,1,'Art. 10.5 EA','La circunscripción electoral es la provincia.',null),
('2-d582fbb6fe','aux-cm',2,'¿Qué porcentaje mínimo de votos necesita una lista para entrar en el reparto de escaños?','["El 3 % de los votos válidos emitidos", "El 5 % del censo electoral", "El 5 % de los votos válidos emitidos", "El 3 % del censo electoral"]'::jsonb,2,'Art. 10.6 EA','Solo entran en el reparto las listas con al menos el 5 % de los sufragios válidamente emitidos.','nov. 2024 · 1.er ejercicio'),
('2-8669c164a5','aux-cm',2,'¿Cuándo se celebran las elecciones a la Asamblea de Madrid?','["El primer domingo de junio", "El último domingo de mayo", "En la fecha que fije libremente el Presidente", "El cuarto domingo de mayo"]'::jsonb,3,'Art. 10.7 EA','Las elecciones se celebran el cuarto domingo de mayo.',null),
('2-dcd80fdf5c','aux-cm',2,'Respecto al mandato de los diputados de la Asamblea:','["Están sujetos al mandato imperativo de su partido", "No están sujetos a mandato imperativo", "Están sujetos al mandato de su Grupo Parlamentario", "Solo hay mandato imperativo en las votaciones de investidura"]'::jsonb,1,'Art. 10.3 EA','Los diputados no están ligados por mandato imperativo.',null),
('2-51ed7e3108','aux-cm',2,'¿Quiénes son electores y elegibles en las elecciones a la Asamblea?','["Los madrileños mayores de 18 años en pleno uso de sus derechos políticos", "Los madrileños mayores de 16 años", "Cualquier residente en la Comunidad, sea cual sea su nacionalidad", "Los madrileños mayores de 18 años con dos años de residencia"]'::jsonb,0,'Art. 10.8 EA','Son electores y elegibles los madrileños mayores de 18 años en pleno uso de sus derechos políticos.',null),
('2-4a4e225b2c','aux-cm',2,'¿Qué mayoría se exige para aprobar el Reglamento de la Asamblea?','["Mayoría simple", "Tres quintos", "Mayoría absoluta", "Dos tercios"]'::jsonb,2,'Art. 12.1 EA','La aprobación y reforma del Reglamento requieren mayoría absoluta de los Diputados.',null),
('2-c4f1561212','aux-cm',2,'¿Cuáles son los periodos ordinarios de sesiones de la Asamblea?','["De septiembre a diciembre y de febrero a junio", "De septiembre a diciembre y de enero a junio", "De octubre a diciembre y de febrero a julio", "Un único periodo de septiembre a junio"]'::jsonb,0,'Art. 14.1 EA','Hay dos periodos ordinarios: de septiembre a diciembre y de febrero a junio.',null),
('2-a182aaf6b2','aux-cm',2,'¿Qué órgano actúa entre los periodos de sesiones de la Asamblea?','["La Mesa", "La Junta de Portavoces", "El Gobierno", "La Diputación Permanente"]'::jsonb,3,'Art. 14.2 EA','Entre periodos de sesiones actúa la Diputación Permanente.',null),
('2-d73c49f6ba','aux-cm',2,'Con carácter general, ¿cómo adopta sus acuerdos la Asamblea?','["Por mayoría absoluta de sus miembros, salvo que se exijan mayorías especiales", "Por mayoría de los miembros presentes, salvo que se exijan mayorías especiales", "Por mayoría de tres quintos, salvo que se exija una mayoría distinta", "Por mayoría de los miembros presentes, sin excepción alguna"]'::jsonb,1,'Art. 14.4 EA','Los acuerdos se adoptan por mayoría de los miembros presentes, salvo mayorías especiales.',null),
('2-285ab1315d','aux-cm',2,'Según el artículo 15, la iniciativa legislativa corresponde a:','["Los diputados, los Grupos Parlamentarios y la Mesa de la Asamblea", "El Gobierno y la Mesa de la Asamblea", "Los diputados, los Grupos Parlamentarios y el Gobierno", "El Presidente de la Comunidad y los Grupos Parlamentarios"]'::jsonb,2,'Art. 15.2 EA','Corresponde a los diputados, a los Grupos Parlamentarios y al Gobierno. Una ley de la Asamblea puede regular además la iniciativa popular y la de los Ayuntamientos.',null),
('2-8eaa56098a','aux-cm',2,'¿Puede la Asamblea delegar la potestad legislativa en el Gobierno?','["No, la potestad legislativa de la Asamblea es indelegable", "Sí, en los términos de los artículos 82 a 84 de la Constitución", "Sí, en los términos que fije cada año la ley de presupuestos", "Solo en materia tributaria y por un plazo máximo de un año"]'::jsonb,1,'Art. 15.3 EA','Solo en los términos de los arts. 82 a 84 de la Constitución.',null),
('2-a8de265a78','aux-cm',2,'¿Qué órganos elige la Asamblea de entre sus miembros?','["El Consejo de Gobierno y el Presidente del TSJ", "El Defensor del Pueblo y la Cámara de Cuentas", "La Mesa y la Junta Electoral", "Su Presidente, la Mesa y la Diputación Permanente"]'::jsonb,3,'Art. 13.1 EA','La Asamblea elige de entre sus miembros a su Presidente, a la Mesa y a la Diputación Permanente.',null),
